    public function ipCheck(Request $request){
        $ip = request()->getClientIp();
        echo $ip;exit;
    }

    public function testDepth(){
//        $bnApi = new GateApi();
//        $data = $bnApi->getDepth('ROSE','USDT');
//        var_dump($data);
        $record = DB::table('user_filter')->get();
        foreach($record as $item){
            $content = json_decode($item->content,true);
            if($content['block_ids']){
                $content['block_ids'] = array_unique($content['block_ids']);
                foreach($content['block_ids'] as $diff_id){
                    DB::table('user_diff_filter')->insert([
                        'diff_id' => $diff_id,
                        'user_id' => $item->user_id
                    ]);
                }
            }
        }
    }
